-- M7: Interview Mode. Generated by drizzle-kit (tables, constraints, indexes), then made re-runnable and extended by hand with the triggers drizzle-kit does not model.
-- IDEMPOTENT on purpose (docs/MIGRATIONS.md section 6.4): IF NOT EXISTS, constraints dropped and re-added, DROP TRIGGER IF EXISTS, CREATE OR REPLACE FUNCTION.
-- Additive: two new append-only tables and two UNIQUE constraints on the immutable M6 tables (they only add a referenceable key; no M6 row, trigger or constraint changes).
-- The existing `assessment_immutable_guard`, `assessment_no_truncate` (migration 0011) and `project_not_voided_guard` (migration 0018) are reused: same rule, same error.

-- 1. The keys the interview records point at (an interview row names a set together with its project AND assessment, and a question together with its set) ---------
-- (added only when absent: a re-run must not drop a key the interview foreign keys already depend on)
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'question_sets_id_project_assessment_key' AND conrelid = 'public.question_sets'::regclass) THEN
    ALTER TABLE "question_sets" ADD CONSTRAINT "question_sets_id_project_assessment_key" UNIQUE("id","project_id","assessment_id");
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'question_set_questions_id_set_key' AND conrelid = 'public.question_set_questions'::regclass) THEN
    ALTER TABLE "question_set_questions" ADD CONSTRAINT "question_set_questions_id_set_key" UNIQUE("id","set_id");
  END IF;
END
$$;
--> statement-breakpoint
-- 2. The records ------------------------------------------------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS "judge_observations" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"project_id" uuid NOT NULL,
	"assessment_id" uuid NOT NULL,
	"question_set_id" uuid,
	"question_id" uuid,
	"team_answer_id" uuid,
	"subject" text NOT NULL,
	"observed" text NOT NULL,
	"outcome" text NOT NULL,
	"recorded_by_actor_id" uuid NOT NULL,
	"recorded_as_role" text NOT NULL,
	"idempotency_key" uuid NOT NULL,
	"request_hash" text NOT NULL,
	"supersedes_observation_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "judge_observations_actor_key_key" UNIQUE("recorded_by_actor_id","idempotency_key"),
	CONSTRAINT "judge_observations_identity_key" UNIQUE("id","project_id","assessment_id"),
	CONSTRAINT "judge_observations_one_correction_key" UNIQUE("supersedes_observation_id"),
	CONSTRAINT "judge_observations_link_shape" CHECK ((question_set_id IS NULL) = (question_id IS NULL) AND (team_answer_id IS NULL OR question_id IS NOT NULL)),
	CONSTRAINT "judge_observations_text_valid" CHECK (char_length(subject) BETWEEN 1 AND 500 AND btrim(subject) <> '' AND subject !~ '[\x01-\x08\x0b\x0c\x0e-\x1f\x7f-\x9f\u202a-\u202e\u2066-\u2069]' AND char_length(observed) BETWEEN 1 AND 4000 AND btrim(observed) <> '' AND observed !~ '[\x01-\x08\x0b\x0c\x0e-\x1f\x7f-\x9f\u202a-\u202e\u2066-\u2069]'),
	CONSTRAINT "judge_observations_outcome_valid" CHECK (outcome IN ('confirmed', 'not_confirmed', 'inconclusive', 'unable_to_verify')),
	CONSTRAINT "judge_observations_role_valid" CHECK (recorded_as_role IN ('judge', 'organizer')),
	CONSTRAINT "judge_observations_hash_hex" CHECK (request_hash ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "judge_observations_not_self_correcting" CHECK (supersedes_observation_id IS DISTINCT FROM id)
);
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "team_answers" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"project_id" uuid NOT NULL,
	"assessment_id" uuid NOT NULL,
