	"recorded_as_role" text NOT NULL,
	"idempotency_key" uuid NOT NULL,
	"request_hash" text NOT NULL,
	"supersedes_answer_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "team_answers_actor_key_key" UNIQUE("recorded_by_actor_id","idempotency_key"),
	CONSTRAINT "team_answers_identity_key" UNIQUE("id","project_id","assessment_id","question_set_id","question_id"),
	CONSTRAINT "team_answers_one_correction_key" UNIQUE("supersedes_answer_id"),
	CONSTRAINT "team_answers_text_valid" CHECK (char_length(answer_text) BETWEEN 1 AND 4000 AND btrim(answer_text) <> '' AND answer_text !~ '[\x01-\x08\x0b\x0c\x0e-\x1f\x7f-\x9f\u202a-\u202e\u2066-\u2069]'),
	CONSTRAINT "team_answers_role_valid" CHECK (recorded_as_role IN ('judge', 'organizer')),
	CONSTRAINT "team_answers_hash_hex" CHECK (request_hash ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "team_answers_not_self_correcting" CHECK (supersedes_answer_id IS DISTINCT FROM id)
);
