-- 3. Append-only: no row is ever updated, deleted or truncated by the application or by direct SQL (an administrator can still run an explicit, reviewed data
--    migration by disabling these triggers inside it). A correction is a NEW row that names the one it supersedes. -------------------------------------------------
DROP TRIGGER IF EXISTS "team_answers_immutable_guard" ON "team_answers";
--> statement-breakpoint
CREATE TRIGGER "team_answers_immutable_guard" BEFORE UPDATE OR DELETE ON "team_answers"
  FOR EACH ROW EXECUTE FUNCTION "assessment_immutable_guard"();
--> statement-breakpoint
DROP TRIGGER IF EXISTS "judge_observations_immutable_guard" ON "judge_observations";
--> statement-breakpoint
CREATE TRIGGER "judge_observations_immutable_guard" BEFORE UPDATE OR DELETE ON "judge_observations"
  FOR EACH ROW EXECUTE FUNCTION "assessment_immutable_guard"();
--> statement-breakpoint
DROP TRIGGER IF EXISTS "team_answers_no_truncate" ON "team_answers";
--> statement-breakpoint
CREATE TRIGGER "team_answers_no_truncate" BEFORE TRUNCATE ON "team_answers"
  FOR EACH STATEMENT EXECUTE FUNCTION "assessment_no_truncate"();
--> statement-breakpoint
DROP TRIGGER IF EXISTS "judge_observations_no_truncate" ON "judge_observations";
--> statement-breakpoint
CREATE TRIGGER "judge_observations_no_truncate" BEFORE TRUNCATE ON "judge_observations"
  FOR EACH STATEMENT EXECUTE FUNCTION "assessment_no_truncate"();
