-- 4. A voided project keeps its interview history readable and starts no new record. The shared guard takes FOR SHARE on the project row, which conflicts with
--    the FOR UPDATE a void takes: a record being written when a void commits is either seen by the void's checks or refused here (no race window). ----------------
DROP TRIGGER IF EXISTS "team_answers_not_voided_guard" ON "team_answers";
--> statement-breakpoint
CREATE TRIGGER "team_answers_not_voided_guard" BEFORE INSERT ON "team_answers"
  FOR EACH ROW EXECUTE FUNCTION "project_not_voided_guard"();
--> statement-breakpoint
DROP TRIGGER IF EXISTS "judge_observations_not_voided_guard" ON "judge_observations";
--> statement-breakpoint
CREATE TRIGGER "judge_observations_not_voided_guard" BEFORE INSERT ON "judge_observations"
  FOR EACH ROW EXECUTE FUNCTION "project_not_voided_guard"();
--> statement-breakpoint

-- 5. The time of a record is the database clock, whatever a writer supplied (no backdating by direct SQL either) ---------------------------------------------------
CREATE OR REPLACE FUNCTION "interview_records_stamp"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW.created_at := clock_timestamp();
  RETURN NEW;
END;
$$;
